<script>document.getElementById('hs-survey-preview').addEventListener('submit',e=>e.preventDefault());function updatePreview(){const form=document.getElementById('hs-survey-preview');form.querySelectorAll('[data-condition-field]').forEach(label=>{const key=label.dataset.conditionField;label.hidden=!!key && form.elements.namedItem(key)?.value!==label.dataset.conditionValue;});}document.getElementById('hs-survey-preview').addEventListener('change',updatePreview);updatePreview();</script>
